mapper.select:
SELECT id, knowledge_base_id, filename, content, embedding, status, created_at, updated_at
FROM rag_document
WHERE id = #{id}

SELECT id, knowledge_base_id, filename, content, embedding, status, created_at, updated_at
FROM rag_document
WHERE knowledge_base_id = #{knowledgeBaseId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM rag_document
WHERE knowledge_base_id = #{knowledgeBaseId}

SELECT id, knowledge_base_id, filename, content, embedding, status, created_at, updated_at
FROM rag_document
WHERE knowledge_base_id = #{knowledgeBaseId} AND status = #{status}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM rag_document
WHERE knowledge_base_id = #{knowledgeBaseId} AND status = #{status}
